-- Siri keyboard shortcut. Generated by System Settings › Apple Intelligence & Siri;
-- press = Type to Siri, hold = speak to Siri (release to send).
local QS = "qs ipc -p " .. (os.getenv("HOME") or "") .. "/.config/quickshell/macos call siri "
hl.bind("SUPER + ALT + S", hl.dsp.exec_cmd(QS .. "keyDown"))
hl.bind("SUPER + ALT + S", hl.dsp.exec_cmd(QS .. "keyUp"), { release = true })
